QImage qimage(const Raster& raster){auto data=raster.rgba();return QImage(data.data(),raster.width,raster.height,raster.width*4,QImage::Format_RGBA8888_Premultiplied).copy();}
class ImageView final:public QWidget {
    QImage image_;QRectF draw_;std::optional<Point> guideStart_;double zoom_{1};std::optional<Point> targetPoint_;double targetY_{};
public:
    std::function<void(Point)> sampled;
    std::function<void(Point,Point)> guided;
    std::function<void(Point,double,Qt::KeyboardModifiers,bool)> targeted;
    std::vector<std::pair<Point,Point>> guides;
    bool drawGuides{},targeting{};
    ImageView(){setObjectName("cameraRawPreview");setMinimumSize(260,200);setSizePolicy(QSizePolicy::Expanding,QSizePolicy::Expanding);setAccessibleName("Camera Raw image preview");}
    void setImage(QImage image){image_=std::move(image);update();}
    const QImage& image()const{return image_;}
protected:
    void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#181b20"));if(image_.isNull())return;QSizeF size=image_.size();size.scale(QSizeF(width(),height())*zoom_,Qt::KeepAspectRatio);draw_={(width()-size.width())/2,(height()-size.height())/2,size.width(),size.height()};p.setRenderHint(QPainter::SmoothPixmapTransform);p.drawImage(draw_,image_);p.setPen(QPen(QColor("#4ca7ef"),2));for(const auto& [a,b]:guides)p.drawLine(QPointF(draw_.x()+a.x*draw_.width(),draw_.y()+(1-a.y)*draw_.height()),QPointF(draw_.x()+b.x*draw_.width(),draw_.y()+(1-b.y)*draw_.height()));}
    std::optional<Point> point(QPointF p)const{if(draw_.isEmpty()||!draw_.contains(p))return {};return Point{(p.x()-draw_.x())/draw_.width(),(p.y()-draw_.y())/draw_.height()};}
    void mousePressEvent(QMouseEvent* e)override{if(e->button()!=Qt::LeftButton)return;auto p=point(e->position());if(!p)return;if(drawGuides)guideStart_=Point{p->x,1-p->y};else if(targeting){targetPoint_=*p;targetY_=e->position().y();if(targeted)targeted(*p,0,e->modifiers(),true);}else if(sampled)sampled(*p);}
    void mouseMoveEvent(QMouseEvent* e)override{if(targetPoint_&&targeted)targeted(*targetPoint_,targetY_-e->position().y(),e->modifiers(),false);}
    void mouseReleaseEvent(QMouseEvent* e)override{targetPoint_.reset();if(guideStart_){auto end=point(e->position());if(end&&guided)guided(*guideStart_,{end->x,1-end->y});guideStart_.reset();}}
    void wheelEvent(QWheelEvent* e)override{zoom_=std::clamp(zoom_*std::pow(1.001,e->angleDelta().y()),.25,8.);update();e->accept();}
};
class Scope final:public QWidget {
    QImage image_;bool vector_{};
public:
    Scope(){setFixedHeight(112);setAccessibleName("Camera Raw histogram");}
    void setImage(const QImage& image){image_=image;update();}void setVector(bool value){vector_=value;update();}
protected:
    void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#15171c"));if(image_.isNull())return;std::array<std::array<int,256>,3> bins{};std::array<int,4096> scope{};int peak=1;for(int y=0;y<image_.height();++y)for(int x=0;x<image_.width();++x){auto c=image_.pixelColor(x,y);if(!c.alpha())continue;if(vector_){double hue=c.hsvHueF()*2*std::numbers::pi,s=c.hsvSaturationF();int xx=std::clamp(int((.5+std::cos(hue)*s*.48)*64),0,63),yy=std::clamp(int((.5+std::sin(hue)*s*.48)*64),0,63);peak=std::max(peak,++scope[size_t(yy)*64+xx]);}else{++bins[0][size_t(c.red())];++bins[1][size_t(c.green())];++bins[2][size_t(c.blue())];}}
        if(vector_){const auto side=std::min(width(),height())-6;const auto left=(width()-side)/2.;p.setPen(QColor("#444951"));p.drawEllipse(QRectF(left,3,side,side));for(int y=0;y<64;++y)for(int x=0;x<64;++x)if(scope[size_t(y)*64+x]){p.setPen(QColor(125,220,170,std::clamp(int(40+215*std::sqrt(scope[size_t(y)*64+x]/double(peak))),0,255)));p.drawPoint(QPointF(left+x*side/64.,3+y*side/64.));}return;}for(const auto& bin:bins)for(int count:bin)peak=std::max(peak,count);const QColor colors[]{QColor(239,102,104,155),QColor(83,216,145,155),QColor(86,157,244,155)};for(size_t c=0;c<3;++c){QPainterPath path;path.moveTo(0,height());for(int i=0;i<256;++i)path.lineTo(i*width()/255.,height()-std::sqrt(bins[c][size_t(i)]/double(peak))*(height()-4));path.lineTo(width(),height());p.fillPath(path,colors[c]);}}
};
class CurveView final:public QWidget {
public:
    std::vector<Point>* points{};std::function<void()> changed;int dragging{-1};
    CurveView(){setMinimumHeight(150);setAccessibleName("Camera Raw point curve; click to add, drag to move, double click to remove");}
protected:
    Point point(QPointF p){return {std::clamp(p.x()/width()*255,0.,255.),std::clamp((1-p.y()/height())*255,0.,255.)};}
    void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#17191e"));p.setPen(QColor("#343941"));for(int i=1;i<4;++i){p.drawLine(i*width()/4,0,i*width()/4,height());p.drawLine(0,i*height()/4,width(),i*height()/4);}if(!points)return;QPainterPath path;for(int x=0;x<width();++x){double y=height()*(1-effects_tools::curveValueUnchecked(*points,x*255./width())/255);if(x==0)path.moveTo(x,y);else path.lineTo(x,y);}p.setPen(QPen(QColor("#a8cfff"),2));p.drawPath(path);p.setBrush(QColor("#4e9aec"));for(auto value:*points)p.drawEllipse(QPointF(value.x/255*width(),(1-value.y/255)*height()),4,4);}
    void mousePressEvent(QMouseEvent* e)override{if(!points)return;const auto v=point(e->position());for(size_t i=0;i<points->size();++i)if(std::abs((*points)[i].x-v.x)<1){dragging=int(i);(*points)[i].y=v.y;if(changed)changed();update();return;}for(size_t i=0;i<points->size();++i)if(std::hypot((*points)[i].x-v.x,(*points)[i].y-v.y)<15){dragging=int(i);return;}if(points->size()>=32||v.x<=1||v.x>=254)return;auto at=std::lower_bound(points->begin(),points->end(),v.x,[](Point p,double x){return p.x<x;});dragging=int(at-points->begin());points->insert(at,v);if(changed)changed();update();}
    void mouseMoveEvent(QMouseEvent* e)override{if(!points||dragging<0)return;auto v=point(e->position());auto& current=(*points)[size_t(dragging)];if(dragging>0&&dragging+1<int(points->size())){const double lo=(*points)[size_t(dragging-1)].x,hi=(*points)[size_t(dragging+1)].x,pad=std::min(1.,(hi-lo)/3);current.x=std::clamp(v.x,lo+pad,hi-pad);}current.y=v.y;if(changed)changed();update();}
    void mouseReleaseEvent(QMouseEvent*)override{dragging=-1;}
    void mouseDoubleClickEvent(QMouseEvent* e)override{if(!points)return;auto p=point(e->position());for(size_t i=1;i+1<points->size();++i)if(std::hypot((*points)[i].x-p.x,(*points)[i].y-p.y)<15){points->erase(points->begin()+i);dragging=-1;if(changed)changed();update();return;}}
};
class GradeWheel final:public QWidget {
public:
    std::function<Point()> value;
    std::function<void(Point)> changed;
    GradeWheel(){setMinimumHeight(154);setMaximumHeight(180);setAccessibleName("Color grading wheel: drag for hue and saturation");setCursor(Qt::CrossCursor);}
protected:
    void paintEvent(QPaintEvent*)override{QPainter p(this);p.setRenderHint(QPainter::Antialiasing);const QPointF center(width()/2.,height()/2.);const double radius=std::min(width(),height())/2.-8;QConicalGradient hue(center,0);for(int i=0;i<=12;++i)hue.setColorAt(i/12.,QColor::fromHsvF(float(i%12/12.),1.f,.85f));p.setPen(Qt::NoPen);p.setBrush(hue);p.drawEllipse(center,radius,radius);QRadialGradient radial(center,radius);radial.setColorAt(0,QColor(220,220,220));radial.setColorAt(1,QColor(220,220,220,0));p.setBrush(radial);p.drawEllipse(center,radius,radius);if(value){auto v=value();const double angle=v.x*std::numbers::pi/180;QPointF selected=center+QPointF(std::cos(angle),-std::sin(angle))*(radius*v.y/100);p.setBrush(Qt::NoBrush);p.setPen(QPen(Qt::black,3));p.drawEllipse(selected,5,5);p.setPen(QPen(Qt::white,1));p.drawEllipse(selected,5,5);}}
    void assign(QPointF point){const double x=point.x()-width()/2.,y=height()/2.-point.y(),radius=std::min(width(),height())/2.-8;double hue=std::atan2(y,x)*180/std::numbers::pi;if(hue<0)hue+=360;if(changed)changed({hue,std::clamp(std::hypot(x,y)/radius*100,0.,100.)});update();}
    void mousePressEvent(QMouseEvent* e)override{if(e->button()==Qt::LeftButton)assign(e->position());}
    void mouseMoveEvent(QMouseEvent* e)override{if(e->buttons().testFlag(Qt::LeftButton))assign(e->position());}
    void mouseDoubleClickEvent(QMouseEvent*)override{if(changed)changed({0,0});update();}
};
class CameraSlider final:public ui::TrackSlider {
public:
    std::function<void()> reset;
    using TrackSlider::TrackSlider;
protected:
    void mouseDoubleClickEvent(QMouseEvent* event)override{if(event->button()==Qt::LeftButton&&reset){reset();event->accept();}else TrackSlider::mouseDoubleClickEvent(event);}
};
class ScrubLabel final:public QLabel {
    QPoint origin_;double start_{};bool dragging_{};
public:
    QDoubleSpinBox* field{};double initial{},sensitivity{1};using QLabel::QLabel;
protected:
    void mousePressEvent(QMouseEvent* e)override{if(e->button()==Qt::LeftButton&&field){origin_=e->globalPosition().toPoint();start_=field->value();dragging_=true;setCursor(Qt::SizeHorCursor);}}
    void mouseMoveEvent(QMouseEvent* e)override{if(dragging_&&field)field->setValue(start_+(e->globalPosition().x()-origin_.x())*sensitivity*(e->modifiers().testFlag(Qt::ShiftModifier)?.1:1));}
    void mouseReleaseEvent(QMouseEvent*)override{dragging_=false;unsetCursor();}
    void mouseDoubleClickEvent(QMouseEvent*)override{dragging_=false;if(field)field->setValue(initial);}
};
