ui::EditPanelSession* openCameraRawPanel(QWidget* parent,const Document& doc,const Layer& layer,ui::EditPanelHost host){if(!layer.raster||layer.group||!layer.adjustmentJson.empty())throw std::runtime_error("Camera Raw requires an image layer");return new CameraPanel(parent,doc,layer,std::move(host));}
